176: // NB: This whole thing assumes that the `xmlsec` callbacks are not re-entrant
177: // (i.e. that xmlsec won't come across a link in the reference it's processing
178: // and try to open that with these callbacks too).
179: typedef struct CbList {
180:   PyObject* match_cb;
181:   PyObject* open_cb;
182:   PyObject* read_cb;
183:   PyObject* close_cb;
184:   struct CbList* next;
185: } CbList;
186: 
187: static CbList* registered_callbacks = NULL;
188: 
189: static void RCBListCons(CbList* cb_list_item) {
190:     cb_list_item->next = registered_callbacks;
191:     registered_callbacks = cb_list_item;
192: }
193: 
194: static void RCBListClear() {
195:     CbList* cb_list_item = registered_callbacks;
196:     while (cb_list_item) {
197:         Py_DECREF(cb_list_item->match_cb);
198:         Py_DECREF(cb_list_item->open_cb);
199:         Py_DECREF(cb_list_item->read_cb);
200:         Py_DECREF(cb_list_item->close_cb);
201:         CbList* next = cb_list_item->next;
202:         free(cb_list_item);
203:         cb_list_item = next;
204:     }
205:     registered_callbacks = NULL;
206: }
