211: static int PyXmlSec_MatchCB(const char* filename) {
212:     cur_cb_list_item = registered_callbacks;
213:     PyGILState_STATE state = PyGILState_Ensure();
214:     PyObject* args = Py_BuildValue("(y)", filename);
215:     while (cur_cb_list_item) {
216:         PyObject* result = PyObject_CallObject(cur_cb_list_item->match_cb, args);
217:         if (result && PyObject_IsTrue(result)) {
218:             Py_DECREF(result);
219:             Py_DECREF(args);
220:             PyGILState_Release(state);
221:             return 1;
222:         }
223:         Py_XDECREF(result);
224:         cur_cb_list_item = cur_cb_list_item->next;
225:     }
226:     Py_DECREF(args);
227:     PyGILState_Release(state);
228:     return 0;
229: }
