231: static void* PyXmlSec_OpenCB(const char* filename) {
232:     PyGILState_STATE state = PyGILState_Ensure();
233: 
234:     // NB: Assumes the match callback left the current callback list item in the
235:     // right place:
236:     PyObject* args = Py_BuildValue("(y)", filename);
237:     PyObject* result = PyObject_CallObject(cur_cb_list_item->open_cb, args);
238:     Py_DECREF(args);
