244: static int PyXmlSec_ReadCB(void* context, char* buffer, int len) {
245:     PyGILState_STATE state = PyGILState_Ensure();
246: 
247:     // NB: Assumes the match callback left the current callback list item in the
248:     // right place:
249:     PyObject* py_buffer = PyMemoryView_FromMemory(buffer, (Py_ssize_t) len, PyBUF_WRITE);
250:     PyObject* args = Py_BuildValue("(OO)", context, py_buffer);
251:     PyObject* py_bytes_read = PyObject_CallObject(cur_cb_list_item->read_cb, args);
252:     Py_DECREF(args);
253:     Py_DECREF(py_buffer);
254:     int result;
255:     if (py_bytes_read && PyLong_Check(py_bytes_read)) {
256:         result = (int)PyLong_AsLong(py_bytes_read);
257:     } else {
258:         result = EOF;
259:     }
260:     Py_XDECREF(py_bytes_read);
