266: static int PyXmlSec_CloseCB(void* context) {
267:     PyGILState_STATE state = PyGILState_Ensure();
268: 
269:     PyObject* args = Py_BuildValue("(O)", context);
270:     PyObject* result = PyObject_CallObject(cur_cb_list_item->close_cb, args);
271:     Py_DECREF(args);
272:     Py_DECREF(context);
273:     Py_DECREF(result);
274: 
275:     PyGILState_Release(state);
276:     return 0;
277: }
